// Contrasts for common senses taught in the training deck.
const antonyms = {
  absence: [{word:'presence',meaning:'在场；出席'}],
  absent: [{word:'present',meaning:'在场的'}],
  accumulate: [{word:'deplete',meaning:'消耗；耗尽',note:'用于资源、储备等。'}],
  adverse: [{word:'favorable',meaning:'有利的'}],
  advocate: [{word:'oppose',meaning:'反对',note:'advocate 作动词表示“提倡”时。'}],
  artificial: [{word:'natural',meaning:'自然的；天然的'}],
  benefit: [{word:'harm',meaning:'损害；伤害',note:'benefit 作动词表示“使受益”时。'}],
  chronic: [{word:'acute',meaning:'急性的',note:'描述疾病的病程或发作方式。'}],
  contaminated: [{word:'uncontaminated',meaning:'未受污染的'}],
  dawn: [{word:'dusk',meaning:'黄昏；暮色'}],
  decline: [{word:'increase',meaning:'增加；上升',note:'用于数量或指标的升降。'}],
  disorderly: [{word:'orderly',meaning:'有秩序的'}],
  employment: [{word:'unemployment',meaning:'失业'}],
  enable: [{word:'disable',meaning:'禁用；使无法运行',note:'用于功能、设备等。'}],
  effectively: [{word:'ineffectively',meaning:'无效地'}],
  excused: [{word:'unexcused',meaning:'未经批准的；无正当理由的',note:'用于缺席、迟到等。'}],
  gain: [{word:'lose',meaning:'失去',note:'用于 gain 作动词表示“获得”时。'}],
  global: [{word:'local',meaning:'本地的；局部的',note:'对比影响或适用范围。'}],
  hamper: [{word:'facilitate',meaning:'促进；使更容易'}],
  harm: [{word:'benefit',meaning:'使受益',note:'用于动词，比较行为带来的影响。'}],
  improve: [{word:'worsen',meaning:'变差；使恶化'}],
  independent: [{word:'dependent',meaning:'依赖的；依附的'}],
  indirect: [{word:'direct',meaning:'直接的'}],
  inequality: [{word:'equality',meaning:'平等；均等'}],
  instability: [{word:'stability',meaning:'稳定性'}],
  irrelevant: [{word:'relevant',meaning:'相关的'}],
  legal: [{word:'illegal',meaning:'不合法的'}],
  likely: [{word:'unlikely',meaning:'不大可能的'}],
  minority: [{word:'majority',meaning:'多数；大多数'}],
  novel: [{word:'familiar',meaning:'熟悉的；常见的',note:'novel 作形容词表示“新颖的”时。'}],
  profit: [{word:'loss',meaning:'亏损',note:'用于收入和成本核算。'}],
  punish: [{word:'reward',meaning:'奖励'}],
  reduce: [{word:'increase',meaning:'增加；提高'}],
  significant: [{word:'insignificant',meaning:'不重要的；微不足道的'}],
  specific: [{word:'general',meaning:'笼统的；一般性的'}],
  stable: [{word:'unstable',meaning:'不稳定的'}],
  strengthen: [{word:'weaken',meaning:'削弱；减弱'}],
  synthetic: [{word:'natural',meaning:'天然的',note:'用于对比材料或成分的来源。'}],
  unexcused: [{word:'excused',meaning:'获准的；有正当理由的',note:'用于缺席、迟到等。'}],
  unique: [{word:'common',meaning:'常见的；普通的',note:'用于对比“独特、少见”与“常见”。'}],
  unusable: [{word:'usable',meaning:'可用的'}],
  usable: [{word:'unusable',meaning:'无法使用的'}],
  wealthy: [{word:'poor',meaning:'贫穷的'}],
  willing: [{word:'unwilling',meaning:'不愿意的'}]
};

export function antonymsFor(word) {
  return Object.hasOwn(antonyms, word) ? antonyms[word] : [];
}
